from __future__ import annotations
import json, hashlib, re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
U4=ROOT/'content'/'ap-biology'/'unit-4'
F3=json.loads((U4/'briefs'/'scene-briefs-f3.json').read_text(encoding='utf-8'))['scene_briefs']
JBRIEFS=json.loads((U4/'briefs'/'journey-briefs-f3.json').read_text(encoding='utf-8'))['journeys']
J7=next(j for j in JBRIEFS if j['journey_id']=='U4-J7')
B={b['locus_id']:b for b in F3 if b['journey_id']=='U4-J7'}

def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()

LOCK_F=json.loads((U4/'content-lock-f4f.json').read_text(encoding='utf-8'))
PREV=[]
for jid in ('U4-J1','U4-J2','U4-J3','U4-J4','U4-J5','U4-J6'):
    rel=f'journeys/{jid}.json'; p=U4/rel
    if not p.exists(): raise RuntimeError(f'F4G requires locked predecessor {rel}')
    expected=LOCK_F['files'][rel]
    if p.stat().st_size!=expected['bytes'] or sha(p)!=expected['sha256']:
        raise RuntimeError(f'F4G refuses to proceed because locked predecessor changed: {rel}')
    PREV.append(json.loads(p.read_text(encoding='utf-8')))
J1,J2,J3,J4,J5,J6=PREV

